/** Generated by scaffold-crud-pages. Query hooks for ExamAttempts.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchExamAttemptsList,
  fetchExamAttemptsById,
  createExamAttempts,
  updateExamAttempts,
  deleteExamAttempts,
  type FetchExamAttemptsListParams,
} from '~/services/httpServices/examAttemptsService';
import type { CreateExamAttemptsRequest, UpdateExamAttemptsRequest } from '~/types/exam-attempts';

const DOMAIN = 'examAttempts';

export function useExamAttemptsList(params?: FetchExamAttemptsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchExamAttemptsList(params),
  });
}

export function useExamAttempts(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchExamAttemptsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateExamAttempts() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateExamAttemptsRequest) => createExamAttempts(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateExamAttempts() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateExamAttemptsRequest }) =>
      updateExamAttempts(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteExamAttempts() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteExamAttempts(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
